[InitializeOnLoad] public static class ForgottenVillagePolish {
 const string Root="Assets/TheForgottenVillage/"; static double next;
 static ForgottenVillagePolish(){EditorApplication.update+=Tick;}
 static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.timeSinceStartup<next)return;if(!EditorApplication.isPlaying&&File.Exists("Verification/polish.request")){File.Delete("Verification/polish.request");next=EditorApplication.timeSinceStartup+2;try{Apply();}catch(Exception e){File.WriteAllText("Verification/polish-results.txt","FAIL: "+e);Debug.LogException(e);}}}
 [MenuItem("Forgotten Village/Apply atmosphere and presentation polish")]
 public static void Request(){File.WriteAllText("Verification/polish.request","run");}
 static TMP_FontAsset font; static Material wood,ink,teal,amber,dustMaterial,signFontMaterial;
 static void Apply(){font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/TextMesh Pro/Resources/Fonts & Materials/LiberationSans SDF.asset");wood=AssetDatabase.LoadAssetAtPath<Material>("Assets/_Course Library/Materials/Object Materials/Material_Wood_Dark.mat");ink=AssetDatabase.LoadAssetAtPath<Material>(Root+"Materials/Ink.mat");teal=AssetDatabase.LoadAssetAtPath<Material>(Root+"Materials/Teal.mat");amber=AssetDatabase.LoadAssetAtPath<Material>(Root+"Materials/Amber.mat");dustMaterial=AssetDatabase.LoadAssetAtPath<Material>(Root+"Materials/AtmosphereDust.mat");signFontMaterial=AssetDatabase.LoadAssetAtPath<Material>(Root+"Materials/Field Sign SDF.mat");if(!signFontMaterial){signFontMaterial=new Material(font.material);signFontMaterial.name="Field Sign SDF";signFontMaterial.SetFloat(ShaderUtilities.ID_OutlineWidth,.12f);signFontMaterial.SetColor(ShaderUtilities.ID_OutlineColor,new Color(.07f,.1f,.14f));AssetDatabase.CreateAsset(signFontMaterial,Root+"Materials/Field Sign SDF.mat");}if(!dustMaterial){var shader=Shader.Find("Universal Render Pipeline/Particles/Unlit");if(!shader)shader=Shader.Find("Sprites/Default");dustMaterial=new Material(shader);dustMaterial.color=new Color(.45f,.59f,.72f,.24f);AssetDatabase.CreateAsset(dustMaterial,Root+"Materials/AtmosphereDust.mat");}var report=new List<string>();
  var village=EditorSceneManager.OpenScene("Assets/Scenes/rpgpp_lt_scene_1.0.unity",OpenSceneMode.Single);PolishVillage(village,report);EditorSceneManager.SaveScene(village);
  for(int i=0;i<6;i++){var scene=EditorSceneManager.OpenScene(Root+"Scenes/"+HouseTransitions.SceneNames[i]+".unity",OpenSceneMode.Single);PolishHouse(scene,i,report);EditorSceneManager.SaveScene(scene);}
  AssetDatabase.SaveAssets();EditorSceneManager.OpenScene("Assets/Scenes/rpgpp_lt_scene_1.0.unity",OpenSceneMode.Single);SeparateHouseBuilder.Validate();File.WriteAllLines("Verification/polish-results.txt",report);Debug.Log("FORGOTTEN_VILLAGE_POLISH_APPLIED");
 }
 static void PolishVillage(Scene scene,List<string> report){var game=scene.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<VillageGame>(true)).FirstOrDefault();if(!game)throw new Exception("VillageGame not found in main village");
  RenderSettings.fog=true;RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogColor=new Color(.61f,.69f,.72f);RenderSettings.fogDensity=.0032f;
  var audio=game.audioFeedback;if(audio){audio.clickAsset=LoadClip("SFX_UI_Click_1");audio.successAsset=LoadClip("SFX_Game_Success");}
  var old=scene.GetRootGameObjects().FirstOrDefault(x=>x.name=="Village Wayfinding & Birds");if(old)UnityEngine.Object.DestroyImmediate(old);var root=new GameObject("Village Wayfinding & Birds");if(game.transitions)game.transitions.outdoorRoots=(game.transitions.outdoorRoots??Array.Empty<GameObject>()).Where(x=>x).Concat(new[]{root}).Distinct().ToArray();var birdObject=new GameObject("Distant mountain birds");birdObject.transform.SetParent(root.transform,false);birdObject.transform.position=game.villageSpawn.position+new Vector3(-9,5,13);var src=birdObject.AddComponent<AudioSource>();src.playOnAwake=false;src.spatialBlend=1;src.volume=.22f;src.minDistance=6;src.maxDistance=34;src.dopplerLevel=0;src.rolloffMode=AudioRolloffMode.Logarithmic;var birds=birdObject.AddComponent<BirdCallAmbience>();birds.game=game;birds.source=src;birds.calls=new[]{LoadClip("SFX_Bird_1"),LoadClip("SFX_Bird_2"),LoadClip("SFX_Bird_3")}.Where(c=>c).ToArray();
  var entranceActions=scene.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<VillageAction>(true)).Where(a=>a.kind=="enter").OrderBy(a=>a.index).ToArray();if(entranceActions.Length!=6)throw new Exception("Expected six village entrance actions");
  for(int i=0;i<entranceActions.Length;i++){var action=entranceActions[i];var label=scene.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<TextMeshPro>(true)).FirstOrDefault(t=>t.text.StartsWith(VillageGame.Houses[i],StringComparison.Ordinal));if(label){label.text=VillageGame.Houses[i].ToUpperInvariant()+"\nE  ?? INVESTIGATE";label.font=font;label.fontStyle=FontStyles.Bold;label.fontSize=1.05f;label.color=i==5?new Color(1,.53f,.35f):new Color(1,.82f,.48f);label.characterSpacing=2;label.fontSharedMaterial=signFontMaterial;label.textWrappingMode=TextWrappingModes.Normal;}
   var plaque=Cube("Directional nameplate ??"+VillageGame.Houses[i],action.transform.position+Vector3.up*2.36f+Vector3.back*.13f,new Vector3(1.22f,.38f,.09f),i==5?ink:wood,root.transform);plaque.transform.rotation=Quaternion.LookRotation((game.villageSpawn.position-plaque.transform.position).normalized,Vector3.up);var sign=Text(VillageGame.Houses[i].ToUpperInvariant(),plaque.transform.position+plaque.transform.forward*.055f,1.12f,.25f,root.transform);sign.transform.rotation=plaque.transform.rotation;sign.fontSize=.28f;sign.fontStyle=FontStyles.Bold;if(i==5){var lockDisplay=scene.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<HouseLockDisplay>(true)).FirstOrDefault();if(lockDisplay){var detail=Text("Locked record counter",action.transform.position+Vector3.up*.85f+Vector3.back*.18f,.95f,.3f,root.transform);detail.transform.rotation=Quaternion.LookRotation((game.villageSpawn.position-detail.transform.position).normalized,Vector3.up);detail.fontSize=.22f;lockDisplay.detailLabel=detail;var chainA=Cube("Locked seal ??crossbar",action.transform.position+new Vector3(0,1.25f,-.13f),new Vector3(.9f,.08f,.1f),amber,root.transform);chainA.transform.rotation=Quaternion.Euler(0,0,36);var chainB=Cube("Locked seal ??brace",action.transform.position+new Vector3(0,1.25f,-.14f),new Vector3(.9f,.07f,.11f),amber,root.transform);chainB.transform.rotation=Quaternion.Euler(0,0,-36);var lockObject=Cube("Five-record brass padlock",action.transform.position+new Vector3(0,1.27f,-.22f),new Vector3(.22f,.25f,.13f),amber,root.transform);var seal=new GameObject("Abandoned House visible sealed gate");seal.transform.SetParent(root.transform,false);foreach(var part in new[]{chainA,chainB,lockObject})part.transform.SetParent(seal.transform,true);lockDisplay.sealVisual=seal;var beacon=new GameObject("Abandoned door warning lamp");beacon.transform.SetParent(root.transform,false);beacon.transform.position=action.transform.position+Vector3.up*2.85f;var light=beacon.AddComponent<Light>();light.type=LightType.Point;light.color=new Color(1,.19f,.07f);light.range=5;light.intensity=.65f;light.shadows=LightShadows.None;var pulse=beacon.AddComponent<GentlePulse>();pulse.target=light;pulse.baseIntensity=.65f;pulse.amplitude=.3f;pulse.frequency=.75f;}}
  }
  report.Add("Village: existing outdoor environment retained; soft distance fog, six illuminated readable entrance plaques, locked laboratory seal, and quiet spatial bird ambience added.");
 }
 static void PolishHouse(Scene scene,int id,List<string> report){var roots=scene.GetRootGameObjects();var house=roots.Select(r=>r.GetComponent<HouseSceneRoot>()).FirstOrDefault(h=>h);if(!house)throw new Exception("HouseSceneRoot missing in "+scene.name);var content=roots.FirstOrDefault(r=>r.GetComponent<HouseSceneRoot>());var oldDressing=content?content.GetComponentsInChildren<Transform>(true).FirstOrDefault(t=>t.name.StartsWith("Atmosphere & set dressing")):null;if(oldDressing)UnityEngine.Object.DestroyImmediate(oldDressing.gameObject);var dressing=new GameObject("Atmosphere & set dressing - "+VillageGame.Houses[id]);if(content)dressing.transform.SetParent(content.transform,false);
  var lamp=content?content.GetComponentsInChildren<Light>(true).FirstOrDefault(l=>l.gameObject.name=="Investigation task light"):null;if(lamp){lamp.shadows=LightShadows.None;lamp.intensity=id==5?1.3f:id==0?2.25f:1.9f;lamp.range=8;}
  string[] ambience={"SFX_Loop_Fire","SFX_Loop_Buzz_1","SFX_Loop_Machine","SFX_Loop_RadioTuning","SFX_Loop_Buzz_2","SFX_Loop_Wind"};var sound=dressing.AddComponent<AudioSource>();sound.clip=LoadClip(ambience[id]);sound.playOnAwake=true;sound.loop=true;sound.spatialBlend=1;sound.volume=id==5?.045f:.032f;sound.minDistance=1.5f;sound.maxDistance=11;sound.dopplerLevel=0;sound.rolloffMode=AudioRolloffMode.Logarithmic;
  HideUnrelatedProps(house.copiedRoots);TintRoom(house.copiedRoots,id);
  if(id==5){RenderSettings.fog=true;RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogColor=new Color(.19f,.24f,.32f);RenderSettings.fogDensity=.009f;foreach(var root in house.copiedRoots.Where(r=>r))foreach(var l in root.GetComponentsInChildren<Light>(true)){l.color=new Color(.55f,.65f,.86f);l.intensity*=.35f;l.shadows=LightShadows.None;}AddAbandonedEvidenceAccents(dressing.transform);AddDust(dressing.transform);}
  else{
   string[][] props={
    new[]{"Storage/Shelving_Traditional","Tables/Table_Side_Traditional","Objects/Books/Book_A_Brown","Objects/Books/Book_C_Green","Objects/Books/Book_B_BrownBlue"},
    new[]{"Storage/Cabinet_Modern_Brown","Storage/Shelving_Modern_Gray","Tables/Table_Side_Modern_Brown","Objects/Containers/Container_Bottle_Blue","Objects/Containers/Container_Bottle_Red","Objects/Electronics/Tablet_Purple","Lighting/Lamp_Table_Blue"},
    new[]{"Storage/Shelving_Modern_Gray","Storage/Drawers_Traditional","Seating/Chair_Rustic_DarkBrown","Objects/Notebooks/Notebook_Brown","Tables/Table_Dining_Traditional_Dark"},
    new[]{"Storage/Cabinet_Modern_Gray","Storage/Drawers_Modern_Dark","Televisions/TV_FlatWallMounted","Objects/Electronics/Clock_Digital","Objects/Electronics/Tablet_Black","Lighting/Lamp_Table_Blue"},
    new[]{"Objects/Electronics/Clock_Analog_Black","Objects/Electronics/Clock_Analog_Red","Objects/Electronics/Clock_Digital","Storage/Shelving_Traditional","Storage/Drawers_Traditional","Seating/Chair_Traditional_Dark","Objects/Books/Book_B_BrownRed"}
   };
   Vector3[][] positions={
    new[]{new Vector3(1.95f,0,.42f),new Vector3(-2.15f,0,.15f),new Vector3(1.55f,1.05f,.42f),new Vector3(1.82f,1.08f,.42f),new Vector3(2.1f,1.02f,.42f)},
    new[]{new Vector3(-2.1f,0,.25f),new Vector3(2.05f,0,.35f),new Vector3(-1.4f,0,-.52f),new Vector3(-1.72f,.82f,.5f),new Vector3(-1.43f,.82f,.5f),new Vector3(.45f,1f,.55f),new Vector3(2.08f,0,-.58f)},
    new[]{new Vector3(2.05f,0,.42f),new Vector3(-2.12f,0,.48f),new Vector3(.98f,0,-.62f),new Vector3(.3f,1f,.62f),new Vector3(-.82f,0,-.72f)},
    new[]{new Vector3(2.05f,0,.45f),new Vector3(-2.08f,0,.48f),new Vector3(2.05f,1.15f,1.55f),new Vector3(2.28f,1.2f,.46f),new Vector3(.48f,1f,.56f),new Vector3(1.95f,0,-.58f)},
    new[]{new Vector3(1.72f,1.75f,1.72f),new Vector3(2.18f,1.75f,1.72f),new Vector3(2.62f,1.75f,1.72f),new Vector3(-2.05f,0,.48f),new Vector3(-2.05f,0,-.5f),new Vector3(.98f,0,-.6f),new Vector3(-1.72f,1.02f,.47f)}
   };
   for(int p=0;p<props[id].Length;p++){var o=Prop(props[id][p],dressing.transform,positions[id][p],1f,id==4?Quaternion.Euler(0,(p%2)*12,0):Quaternion.identity);if(id==3&&p==2&&o)o.transform.localRotation=Quaternion.Euler(0,180,0);}
   if(id==1||id==2||id==3){for(int n=0;n<3;n++){var caseBox=Cube(id==1?"Glass reagent vessel":id==2?"Cut timber and component case":"Instrument cable coil",new Vector3(-1.25f+n*.19f,.8f,.48f),new Vector3(.13f,.18f,.13f),n%2==0?teal:amber,dressing.transform);if(id==3)caseBox.transform.localScale=new Vector3(.34f,.035f,.035f);}}
   if(id==4){for(int g=0;g<3;g++){var gear=GameObject.CreatePrimitive(PrimitiveType.Cylinder);gear.name="Clockmaker brass timing wheel";gear.transform.SetParent(dressing.transform,false);gear.transform.localPosition=new Vector3(-1.45f+g*.48f,1.8f,1.71f);gear.transform.localRotation=Quaternion.Euler(90,0,0);gear.transform.localScale=new Vector3(.32f,.06f,.32f);gear.GetComponent<Renderer>().sharedMaterial=amber;UnityEngine.Object.DestroyImmediate(gear.GetComponent<Collider>());}}
   AddPuzzlePlaque(dressing.transform,id);
  }
  // Keep the original interaction labels, but style them as small physical room signage.
  foreach(var text in house.copiedRoots.Where(r=>r).SelectMany(r=>r.GetComponentsInChildren<TextMeshPro>(true))){
   if(text.text.StartsWith("ENGINEERING STATION",StringComparison.Ordinal)){text.text="ENGINEERING PUZZLE";text.fontSize=.42f;text.fontSizeMin=.38f;text.fontSizeMax=.42f;text.enableAutoSizing=false;text.characterSpacing=.3f;text.color=new Color(.96f,.79f,.48f);text.rectTransform.sizeDelta=new Vector2(1.55f,.34f);}
   else if(text.text=="TALK"){text.text="SPEAK";text.fontSize=.36f;text.fontSizeMin=.32f;text.fontSizeMax=.36f;text.enableAutoSizing=false;text.rectTransform.sizeDelta=new Vector2(.7f,.3f);}
  }
  AddNPCIdle(content);report.Add(VillageGame.Houses[id]+": distinct course-library furniture, focused themed lighting and room tone added; oversized labels refined; puzzle calculations and interaction bindings retained.");
 }
  static void HideUnrelatedProps(GameObject[] roots){string[] names={"Tennis_Racket_Blue","Tennis_Ball_Green","Hat_Captain_Black","Hat_Top"};foreach(var root in roots.Where(r=>r))foreach(var t in root.GetComponentsInChildren<Transform>(true))if(names.Any(n=>t.name.StartsWith(n,StringComparison.Ordinal)))t.gameObject.SetActive(false);}
  static void TintRoom(GameObject[] roots,int id){Color[] colors={new Color(1f,.9f,.78f),new Color(.72f,.94f,.88f),new Color(.96f,.78f,.59f),new Color(.72f,.82f,.98f),new Color(.98f,.9f,.67f),new Color(.53f,.65f,.8f)};foreach(var root in roots.Where(r=>r))foreach(var renderer in root.GetComponentsInChildren<MeshRenderer>(true)){string n=renderer.name;if(!n.StartsWith("Room_Rustic_Panel",StringComparison.Ordinal)&&!n.StartsWith("Room_Rustic_Ceiling",StringComparison.Ordinal))continue;var mats=renderer.sharedMaterials;bool dirty=false;for(int i=0;i<mats.Length;i++){if(!mats[i])continue;string safe=new string(mats[i].name.Select(c=>char.IsLetterOrDigit(c)?c:'_').ToArray());string path=Root+"Materials/HouseSurface_"+id+"_"+safe+".mat";var tint=AssetDatabase.LoadAssetAtPath<Material>(path);if(!tint){tint=new Material(mats[i]);tint.name="House surface " + id + " " + safe;if(tint.HasProperty("_BaseColor"))tint.SetColor("_BaseColor",colors[id]);if(tint.HasProperty("_Color"))tint.SetColor("_Color",colors[id]);AssetDatabase.CreateAsset(tint,path);}mats[i]=tint;dirty=true;}if(dirty)renderer.sharedMaterials=mats;}}
  static float TargetSize(string p){if(p.Contains("Shelving")||p.Contains("Fireplace"))return 1.72f;if(p.Contains("Couch"))return 1.65f;if(p.Contains("Cabinet"))return 1.38f;if(p.Contains("Drawers"))return 1.2f;if(p.Contains("Rug"))return 2.0f;if(p.Contains("Chair"))return .95f;if(p.Contains("Table"))return 1.1f;if(p.Contains("TV_"))return 1.05f;if(p.Contains("Clock_"))return .62f;if(p.Contains("Book_"))return .34f;if(p.Contains("Bottle"))return .28f;if(p.Contains("Tablet"))return .5f;if(p.Contains("Lamp"))return .82f;if(p.Contains("Notebook"))return .4f;return .68f;}
  static void AddPuzzlePlaque(Transform parent,int id){string[] titles={"THE LOADED DIVIDER","MEMORY SIGNAL FILTER","COMMON-SOURCE AMPLIFIER","MIC-17 SAFETY CONTROLLER","REGISTER SETUP ANALYSIS"};string[] lines={"R1 10 kohm; R2 10 kohm\nRlow = R2 || RL\nTarget: loaded Vout = 4.00 V","fc = 1/(2*pi*R*C)\nPass 100 Hz; reject 5 kHz\nThe potentiometer adjusts R","Av approx -gm x (RD || RL)\ngm=2 mS; target gain=-8\nNegative gain means inversion","DEPLOYED: by-value -> RUN\nFIX: const reference -> STOP\nCompare code with runtime logs","Slack = required - arrival\nT=10 ns starts at -1.5 ns\nTiming risk is not causation"};var board=Cube("Engineering field card",new Vector3(-1.35f,1.45f,1.78f),new Vector3(1.5f,.68f,.09f),ink,parent);var border=Cube("Brass field card edge",new Vector3(-1.35f,1.45f,1.83f),new Vector3(1.56f,.73f,.035f),amber,parent);border.transform.SetParent(board.transform,true);var text=Text(titles[id]+"\n"+lines[id],new Vector3(-1.35f,1.45f,1.724f),1.42f,.62f,parent);text.fontSize=.16f;text.fontSizeMin=.13f;text.fontStyle=FontStyles.Bold;text.alignment=TextAlignmentOptions.Center;text.color=new Color(.97f,.88f,.67f);text.characterSpacing=.5f;}
  static void AddAbandonedEvidenceAccents(Transform parent){Prop("Televisions/TV_FlatWithStand",parent,new Vector3(2.12f,1.05f,1.38f),1f,Quaternion.Euler(0,180,0));Prop("Storage/Chest_Traditional",parent,new Vector3(-2.08f,0,-.55f),1f,Quaternion.identity);Prop("Storage/Drawers_Modern_Dark",parent,new Vector3(2.12f,0,-.62f),1f,Quaternion.identity);Prop("Objects/Notebooks/Notebook_Stripes",parent,new Vector3(.85f,.93f,-.65f),1f,Quaternion.Euler(0,18,0));Prop("Lighting/Lightsource_Lantern",parent,new Vector3(1.8f,1.0f,-.52f),1f,Quaternion.identity);var board=Cube("Final evidence comparison console",new Vector3(-1.28f,1.2f,1.72f),new Vector3(1.58f,.55f,.12f),ink,parent);var title=Text("MIC-17 / EXPERIMENT 06\nSOFTWARE LOG: RUN | SAFE FIX: STOP\nTIMING SLACK: -1.5 ns / POSSIBLE RISK\nIDENTITY FILE: NAME STILL SEALED",new Vector3(-1.28f,1.2f,1.65f),1.48f,.48f,parent);title.fontSize=.13f;title.fontSizeMin=.1f;title.fontStyle=FontStyles.Bold;title.color=new Color(.94f,.7f,.56f);var cable=Cube("Broken cable at evidence station",new Vector3(-1.6f,.42f,.7f),new Vector3(.8f,.035f,.035f),amber,parent);cable.transform.rotation=Quaternion.Euler(0,0,17);}
 static void AddNPCIdle(GameObject content){if(!content)return;var resident=content.GetComponentsInChildren<VillageAction>(true).FirstOrDefault(a=>a.kind=="dialogue");if(!resident)return;var idle=resident.gameObject.GetComponent<ResidentIdle>();if(!idle)idle=resident.gameObject.AddComponent<ResidentIdle>();idle.body=content.GetComponentsInChildren<Transform>(true).FirstOrDefault(t=>t.name=="Resident coat");idle.head=content.GetComponentsInChildren<Transform>(true).FirstOrDefault(t=>t.name=="Resident face");}
 static void AddBooks(Transform parent,Vector3[] points){string[] names={"Objects/Books/Book_A_Brown","Objects/Books/Book_C_Green","Objects/Books/Book_B_BrownBlue"};for(int i=0;i<points.Length;i++)Prop(names[i],parent,points[i],.32f,Quaternion.Euler(0,0,i%2==0?0:90));}
 static void AddDust(Transform parent){var go=new GameObject("Slow suspended lab dust");go.transform.SetParent(parent,false);go.transform.localPosition=new Vector3(0,1.3f,.4f);var ps=go.AddComponent<ParticleSystem>();var main=ps.main;main.loop=true;main.startLifetime=12;main.startSpeed=.025f;main.startSize=.018f;main.startColor=new Color(.45f,.59f,.72f,.24f);main.maxParticles=30;var emission=ps.emission;emission.rateOverTime=2;var shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Box;shape.scale=new Vector3(4,2.2f,2.6f);var renderer=ps.GetComponent<ParticleSystemRenderer>();renderer.renderMode=ParticleSystemRenderMode.Billboard;renderer.sharedMaterial=dustMaterial;}
 
  static GameObject Prop(string relative,Transform parent,Vector3 p,float scale,Quaternion rotation){string path="Assets/_Course Library/_Prefabs/"+relative+".prefab";var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(!prefab)return null;var o=(GameObject)PrefabUtility.InstantiatePrefab(prefab);o.name=prefab.name+" room dressing";o.transform.SetParent(parent,false);o.transform.localPosition=p;o.transform.localRotation=rotation;o.transform.localScale=Vector3.one*scale;var renderers=o.GetComponentsInChildren<Renderer>(true);if(renderers.Length>0){Bounds b=renderers[0].bounds;foreach(var r in renderers)b.Encapsulate(r.bounds);float max=Mathf.Max(b.size.x,Mathf.Max(b.size.y,b.size.z));if(max>.001f)o.transform.localScale*=TargetSize(relative)/max;}return o;}
 static AudioClip LoadClip(string name){string[] ids=AssetDatabase.FindAssets(name+" t:AudioClip",new[]{"Assets/_Course Library/Audio"});foreach(var id in ids){var p=AssetDatabase.GUIDToAssetPath(id);if(Path.GetFileNameWithoutExtension(p)==name)return AssetDatabase.LoadAssetAtPath<AudioClip>(p);}return null;}
 static GameObject Cube(string name,Vector3 p,Vector3 size,Material material,Transform parent){var o=GameObject.CreatePrimitive(PrimitiveType.Cube);o.name=name;o.transform.SetParent(parent,false);o.transform.localPosition=p;o.transform.localScale=size;if(material)o.GetComponent<Renderer>().sharedMaterial=material;var collider=o.GetComponent<Collider>();if(collider)collider.enabled=false;return o;}
 static TextMeshPro Text(string text,Vector3 p,float width,float height,Transform parent){var go=new GameObject("Field signage ??"+text.Split('\n')[0],typeof(TextMeshPro));go.transform.SetParent(parent,false);go.transform.localPosition=p;var t=go.GetComponent<TextMeshPro>();t.font=font;t.text=text;t.fontSize=.32f;t.fontSizeMin=.1f;t.fontSizeMax=.32f;t.enableAutoSizing=true;t.alignment=TextAlignmentOptions.Center;t.color=new Color(1,.86f,.62f);t.fontSharedMaterial=signFontMaterial;t.rectTransform.sizeDelta=new Vector2(width,height);return t;}
}
